import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { lstatSync, readFileSync, readdirSync } from 'node:fs';
import { join, extname, basename } from 'node:path';
import { gunzipSync } from 'node:zlib';
import { Buffer } from 'node:buffer';
import process from 'node:process';

export const TARGETS = Object.freeze(['linux-arm64', 'linux-x64', 'darwin-arm64', 'darwin-x64', 'win32-x64']);
const WINDOWS_RUNTIME_NOTICES = ['native/dependencies/licenses/mingw-w64-runtime-COPYING', 'native/dependencies/licenses/gcc-COPYING.RUNTIME'];
export const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
const keys = (value, expected) => {
  assert(value && typeof value === 'object' && !Array.isArray(value), 'Expected an object');
  assert.deepEqual(Object.keys(value).sort(), [...expected].sort(), 'Unexpected object fields');
};
const hash = value => assert.match(value, /^[a-f0-9]{64}$/, 'Invalid SHA256');
const safePath = name => {
  assert(typeof name === 'string' && name.length <= 240 && name.split('/').every(part => /^[A-Za-z0-9_.-]+$/.test(part) && part !== '.' && part !== '..'), 'Invalid archive path');
  return name;
};
export function regularFile(root, name, limit = 64 * 1024 * 1024) {
  safePath(name); let path = root;
  assert(lstatSync(path).isDirectory() && !lstatSync(path).isSymbolicLink(), 'Invalid package root');
  for (const part of name.split('/')) { path = join(path, part); assert(!lstatSync(path).isSymbolicLink(), 'Symlink refused'); }
  const stat = lstatSync(path); assert(stat.isFile() && stat.size > 0 && stat.size <= limit, 'Invalid regular file');
  const bytes = readFileSync(path); assert.equal(bytes.length, stat.size); return bytes;
}
export function verifyPackageIdentity(path, receipt, sourceSha) {
  assert.match(sourceSha, /^[a-f0-9]{40}$/); assert.equal(receipt.sha, sourceSha, 'Package source mismatch');
  assert.equal(typeof receipt.name, 'string'); assert.equal(typeof receipt.version, 'string');
  assert.equal(receipt.integrity, 'sha512-' + createHash('sha512').update(readFileSync(path)).digest('base64'), 'Final npm artifact integrity mismatch');
}

// Corresponding source is generated by Python tarfile with regular entries.
// Read without extraction; bound compressed/expanded sizes and metadata too.
export function readSourceArchive(bytes, maximum = 320 * 1024 * 1024) {
  assert(bytes.length <= 160 * 1024 * 1024, 'Compressed source limit exceeded');
  const tar = gunzipSync(bytes, { maxOutputLength: maximum }); const files = new Map();
  let at = 0; let pending;
  const text = bytes => bytes.subarray(0, bytes.indexOf(0) < 0 ? bytes.length : bytes.indexOf(0)).toString('utf8');
  const octal = bytes => { const value = text(bytes).trim(); assert(/^[0-7]+$/.test(value)); return parseInt(value, 8); };
  while (at + 512 <= tar.length) {
    const header = tar.subarray(at, at + 512); at += 512;
    if (header.every(byte => byte === 0)) {
      assert(!pending && tar.subarray(at).every(byte => byte === 0), 'Hidden source archive tail'); return files;
    }
    let checksum = 0; for (let i = 0; i < 512; i++) checksum += i >= 148 && i < 156 ? 32 : header[i];
    assert.equal(octal(header.subarray(148, 156)), checksum, 'Source tar checksum mismatch');
    const size = octal(header.subarray(124, 136)); assert(size <= 128 * 1024 * 1024 && at + size <= tar.length, 'Invalid source tar size');
    const data = tar.subarray(at, at + size); at += Math.ceil(size / 512) * 512;
    const type = header[156];
    if (type === 120) {
      assert(!pending && size <= 4096, 'Invalid source PAX header'); pending = {};
      let offset = 0;
      while (offset < data.length) {
        const space = data.indexOf(32, offset); assert(space > offset); const digits = data.subarray(offset, space).toString();
        assert(/^[0-9]+$/.test(digits)); const length = Number(digits); assert(length > space - offset + 2 && offset + length <= data.length && data[offset + length - 1] === 10);
        const field = data.subarray(space + 1, offset + length - 1).toString(); const split = field.indexOf('='); assert(split > 0);
        const key = field.slice(0, split); assert(['path', 'mtime', 'atime', 'ctime'].includes(key) && !Object.hasOwn(pending, key), 'Unsupported source PAX metadata');
        pending[key] = field.slice(split + 1); offset += length;
      }
      continue;
    }
    assert(type === 0 || type === 48, 'Source archive links and nonregular members refused');
    const prefix = text(header.subarray(345, 500)); const name = safePath(pending?.path ?? ((prefix ? prefix + '/' : '') + text(header.subarray(0, 100)))); pending = undefined;
    assert(!files.has(name) && files.size < 512, 'Duplicate or excessive source members'); files.set(name, data);
  }
  throw new Error('Unterminated source archive');
}

export function collectSourceProof(root, sourceSha) {
  assert.match(sourceSha, /^[a-f0-9]{40}$/);
  const listing = execFileSync('git', ['-C', root, 'ls-tree', '-rzl', sourceSha, '--', 'native', '.github/workflows/test.yml'], { maxBuffer: 2 * 1024 * 1024 }).toString();
  const sources = {}; let total = 0; let pins; let recipeSha;
  for (const row of listing.split('\0').filter(Boolean)) {
    const [metadata, path] = row.split('\t');
    if (!(path === '.github/workflows/test.yml' || path.startsWith('native/dependencies/licenses/') || ['.c', '.h', '.inc', '.py', '.md'].includes(extname(path)) || ['Makefile', 'COPYING', 'source-inputs.json'].includes(basename(path)))) continue;
    safePath(path); const [mode, kind, , size] = metadata.split(/\s+/);
    assert(['100644', '100755'].includes(mode) && kind === 'blob' && (total += Number(size)) <= 16 * 1024 * 1024 && Object.keys(sources).length < 256);
    const data = execFileSync('git', ['-C', root, 'show', `${sourceSha}:${path}`], { maxBuffer: 16 * 1024 * 1024 }); assert.equal(data.length, Number(size));
    sources[path] = sha256(data);
    if (path === 'native/dependencies/prepare.py') recipeSha = sha256(data);
    if (path === 'native/dependencies/source-inputs.json') pins = JSON.parse(data);
  }
  for (const path of ['native/worker.c', 'native/Makefile', 'native/COPYING', 'native/dependencies/package.py', '.github/workflows/test.yml',
    'native/dependencies/licenses/ffmpeg-LICENSE.md', 'native/dependencies/licenses/opus-COPYING', 'native/dependencies/licenses/x264-COPYING', 'native/dependencies/licenses/libsrtp-LICENSE',
    ...WINDOWS_RUNTIME_NOTICES]) assert(sources[path], 'Missing exact corresponding source');
  assert(recipeSha && pins?.sources?.length === 4); return { sourceSha, recipeSha, pins, sources };
}

export function verifyNativePackage(root, proof) {
  for (const path of WINDOWS_RUNTIME_NOTICES) assert(proof.sources[path], 'Missing Windows runtime notice provenance');
  const read = (path, limit) => regularFile(root, path, limit);
  const manifestBytes = read('native/runtime/manifest.json', 65536); const manifest = JSON.parse(manifestBytes);
  const distribution = JSON.parse(read('native/runtime/distribution-receipt.json', 2 * 1024 * 1024));
  keys(manifest, ['schemaVersion', 'targets']); assert.equal(manifest.schemaVersion, 1); keys(manifest.targets, TARGETS);
  keys(distribution, ['schemaVersion', 'source_sha', 'targets', 'manifest_sha256', 'source_bundle_sha256', 'distribution_ready']);
  assert.equal(distribution.schemaVersion, 1); assert.equal(distribution.source_sha, proof.sourceSha, 'Native source mismatch');
  assert.equal(distribution.distribution_ready, false, 'Build receipts cannot declare distribution acceptance'); keys(distribution.targets, TARGETS);
  assert.equal(distribution.manifest_sha256, sha256(manifestBytes), 'Native manifest hash mismatch');
  const expectedFiles = new Set(['manifest.json', 'distribution-receipt.json']);
  for (const target of TARGETS) {
    const entry = manifest.targets[target]; keys(entry, ['path', 'sha256']); hash(entry.sha256);
    const relative = `${target}/worker${target === 'win32-x64' ? '.exe' : ''}`; expectedFiles.add(relative);
    assert.equal(entry.path, `native/runtime/${relative}`, 'Native target path mismatch');
    const bytes = read(entry.path); assert.equal(sha256(bytes), entry.sha256, 'Native binary hash mismatch');
    if (process.platform !== 'win32') assert(lstatSync(join(root, entry.path)).mode & 0o111, 'Native executable mode missing');
    const receipt = distribution.targets[target];
    keys(receipt, ['target', 'source_sha', 'sha256', 'dependencies', 'dynamic_dependencies', 'distribution_ready', 'limitations', 'artifact_sha256']);
    assert.equal(receipt.target, target); assert.equal(receipt.source_sha, proof.sourceSha); assert.equal(receipt.sha256, entry.sha256); hash(receipt.artifact_sha256);
    assert.equal(receipt.distribution_ready, false); assert.equal(receipt.dependencies.recipe_sha256, proof.recipeSha, 'Native dependency recipe mismatch');
    assert.deepEqual(receipt.dependencies.source_inputs, proof.pins, 'Native pinned inputs mismatch');
    assert(typeof receipt.dynamic_dependencies === 'string' && receipt.dynamic_dependencies.length > 0 && Array.isArray(receipt.limitations));
  }
  const actual = new Set();
  for (const name of readdirSync(join(root, 'native/runtime'))) {
    const path = join(root, 'native/runtime', name); const stat = lstatSync(path); assert(!stat.isSymbolicLink(), 'Native symlink refused');
    if (stat.isDirectory()) { assert(TARGETS.includes(name)); for (const file of readdirSync(path)) actual.add(`${name}/${file}`); }
    else { assert(stat.isFile()); actual.add(name); }
  }
  assert.deepEqual(actual, expectedFiles, 'Native runtime inventory mismatch');
  assert.deepEqual(readdirSync(join(root, 'native')).sort(), ['COPYING', 'NOTICE', 'corresponding-source.tar.gz', 'runtime'].sort(), 'Unexpected packaged native content');
  assert.equal(sha256(read('native/COPYING', 128 * 1024)), proof.sources['native/COPYING'], 'Native license mismatch'); read('native/NOTICE', 65536);
  const bundle = read('native/corresponding-source.tar.gz', 160 * 1024 * 1024); assert.equal(sha256(bundle), distribution.source_bundle_sha256, 'Source bundle hash mismatch');
  const files = readSourceArchive(bundle); const expected = new Set(['README.md', 'dependencies/ffmpeg-9.0.2.tar.xz.asc', 'dependencies/ffmpeg-devel.asc']);
  for (const [path, digest] of Object.entries(proof.sources)) { expected.add('project/' + path); assert.equal(sha256(files.get('project/' + path) ?? Buffer.alloc(0)), digest, 'Corresponding project source mismatch'); }
  for (const input of proof.pins.sources) { expected.add('dependencies/' + input.filename); assert.equal(sha256(files.get('dependencies/' + input.filename) ?? Buffer.alloc(0)), input.sha256, 'Corresponding dependency archive mismatch'); }
  for (const target of TARGETS) { const path = `receipts/${target}.json`; expected.add(path); assert.deepEqual(JSON.parse(files.get(path)), distribution.targets[target], 'Bundled target receipt mismatch'); }
  assert.deepEqual(new Set(files.keys()), expected, 'Corresponding source inventory mismatch');
  for (const name of ['README.md', 'dependencies/ffmpeg-9.0.2.tar.xz.asc', 'dependencies/ffmpeg-devel.asc']) assert(files.get(name)?.length > 0, 'Missing source rebuild/signature input');
  return distribution;
}
